//! Filter rules editor (Bulwark components/filters/filter-rule-modal.tsx, filter-settings.tsx,
//! lib/filters/retroactive.ts): edit existing rules, reorder them, several conditions with
//! all/any, several actions, header / size / regex / attachment conditions, not_is, reject /
//! keep / stop, active period, spam opt-in, and running a rule over the Inbox.
//! The script is generated by sieve.rs and saved through server_settings::save_script.
use crate::jmap::Client;
use crate::server_settings::Shared as Cache;
use crate::{AppWindow, FAct, FCond, FilterX};
use serde_json::{json, Map, Value};
use slint::{ComponentHandle, ModelRc, SharedString, VecModel};
use std::cell::RefCell;
use std::sync::{Arc, Mutex};

pub type ClientSlot = Arc<Mutex<Option<Arc<Client>>>>;
pub type Reload = Arc<dyn Fn(String) + Send + Sync>;

pub const FIELDS: [(&str, &str); 9] = [("from", "From"), ("to", "To"), ("cc", "Cc"), ("subject", "Subject"), ("header", "Custom header"),
    ("size", "Size"), ("body", "Body"), ("attachment", "Attachment"), ("all", "All messages")];

const CMP_LABELS: [(&str, &str); 16] = [("contains", "contains"), ("not_contains", "does not contain"), ("is", "is exactly"), ("not_is", "is not"),
    ("starts_with", "starts with"), ("ends_with", "ends with"), ("matches", "matches pattern"), ("regex", "matches regex"), ("address_is", "is the address"),
    ("domain_is", "has the domain"), ("greater_than", "is greater than"), ("less_than", "is less than"), ("has_any", "is present"), ("has_type", "of type"),
    ("any", ""), ("", "")];

/// The comparators a field allows (Bulwark filter-rule-modal COMPARATORS_BY_FIELD).
pub fn comparators(field: &str) -> Vec<&'static str> {
    match field {
        "from" | "to" | "cc" => vec!["contains", "not_contains", "is", "not_is", "starts_with", "ends_with", "matches", "regex", "address_is", "domain_is"],
        "subject" | "header" => vec!["contains", "not_contains", "is", "not_is", "starts_with", "ends_with", "matches", "regex"],
        "body" => vec!["contains", "is", "regex"],
        "size" => vec!["greater_than", "less_than"],
        "attachment" => vec!["has_any", "has_type"],
        _ => vec![],
    }
}

fn cmp_label(c: &str) -> &'static str { CMP_LABELS.iter().find(|x| x.0 == c).map(|x| x.1).unwrap_or("") }

/// (type, label, what it needs)
pub const ACTS: [(&str, &str, &str); 10] = [("move", "Move to folder", "folder"), ("copy", "Copy to folder", "folder"), ("forward", "Forward to", "address"),
    ("mark_read", "Mark as read", ""), ("star", "Star message", ""), ("add_label", "Add tag", "tag"), ("discard", "Discard (delete silently)", ""),
    ("reject", "Reject with message", "text"), ("keep", "Keep in inbox", ""), ("stop", "Don't apply later rules", "")];

/// The ACTS indices an action row offers on a server with these Sieve extensions (G-020: reject
/// only when listed). The row's own type stays in the list, so an existing rule still shows it.
pub fn offered_acts(ext: &[String], current: &str) -> Vec<usize> {
    (0..ACTS.len()).filter(|&i| ACTS[i].0 == current || crate::sieve::action_offered(ACTS[i].0, ext)).collect()
}

/// The server's Sieve extensions as the filters tab loaded them (empty before that).
fn sieve_ext() -> Vec<String> {
    CACHE.with(|c| c.borrow().as_ref().map(|k| k.lock().unwrap().sieve_ext.clone())).unwrap_or_default()
}

#[derive(Clone, Default, Debug)]
pub struct Cond { pub field: String, pub cmp: String, pub value: String, pub header: String }
#[derive(Clone, Default, Debug)]
pub struct Act { pub kind: String, pub value: String, pub mailbox: String, pub keep_copy: bool }

#[derive(Default)]
struct Ed {
    id: Option<String>,
    base: Value,
    conds: Vec<Cond>,
    acts: Vec<Act>,
    /// (mailbox id, path)
    folders: Vec<(String, String)>,
}

#[derive(Default)]
#[allow(dead_code)]
struct Retro { rule: Value, plan: Vec<(String, Vec<String>, String)>, gen: u64, state: String }

thread_local! {
    static CACHE: RefCell<Option<Cache>> = const { RefCell::new(None) };
    static ED: RefCell<Ed> = RefCell::new(Ed::default());
    static RETRO: RefCell<Retro> = RefCell::new(Retro::default());
}

fn sv(v: &str) -> SharedString { SharedString::from(v) }
fn model<T: Clone + 'static>(v: Vec<T>) -> ModelRc<T> { ModelRc::new(VecModel::from(v)) }

/// Folder paths as Sieve's fileinto names them ("Parent/Child"), by path.
pub fn folder_paths(boxes: &[Value]) -> Vec<(String, String)> {
    let by_id: std::collections::HashMap<&str, &Value> = boxes.iter().filter_map(|b| b["id"].as_str().map(|i| (i, b))).collect();
    let mut out: Vec<(String, String)> = boxes.iter().map(|b| {
        let mut parts = vec![b["name"].as_str().unwrap_or("").to_string()];
        let mut p = b["parentId"].as_str();
        let mut guard = 0;
        while let Some(pid) = p { let Some(pb) = by_id.get(pid) else { break }; parts.push(pb["name"].as_str().unwrap_or("").to_string()); p = pb["parentId"].as_str(); guard += 1; if guard > 20 { break; } }
        parts.reverse();
        let path = if b["role"] == "inbox" { "INBOX".to_string() } else { parts.join("/") };
        (b["id"].as_str().unwrap_or("").to_string(), path)
    }).collect();
    out.sort_by_key(|(_, p)| (p != "INBOX", p.to_lowercase()));
    out
}

fn values_text(v: &Value) -> String {
    match v { Value::Array(a) => a.iter().filter_map(|x| x.as_str()).collect::<Vec<_>>().join(", "), Value::String(s) => s.clone(), Value::Number(n) => n.to_string(), _ => String::new() }
}

pub fn conds_of(rule: &Value) -> Vec<Cond> {
    rule["conditions"].as_array().map(|a| a.iter().map(|c| Cond {
        field: c["field"].as_str().unwrap_or("from").into(), cmp: c["comparator"].as_str().unwrap_or("contains").into(),
        value: values_text(&c["value"]), header: c["headerName"].as_str().unwrap_or("").into(),
    }).collect()).unwrap_or_default()
}

pub fn acts_of(rule: &Value) -> Vec<Act> {
    rule["actions"].as_array().map(|a| a.iter().map(|x| Act {
        kind: x["type"].as_str().unwrap_or("move").into(), value: x["value"].as_str().unwrap_or("").into(),
        mailbox: x["mailboxId"].as_str().unwrap_or("").into(), keep_copy: x["keepCopy"] == true,
    }).collect()).unwrap_or_default()
}

fn valid_email(e: &str) -> bool {
    let Some((l, d)) = e.split_once('@') else { return false };
    !l.is_empty() && d.contains('.') && !e.contains(char::is_whitespace) && !d.starts_with('.') && !d.ends_with('.')
}

/// The header names the Sieve generator writes (it skips rules with any other name, sieve.rs).
fn header_ok(h: &str) -> bool { !h.is_empty() && h.chars().all(|ch| ch.is_ascii_alphanumeric() || ch == '_' || ch == '-') }

/// The rule as Bulwark stores it, from the form; Err with what to fix.
#[allow(clippy::too_many_arguments)]
pub fn build_rule(base: &Value, id: Option<&str>, name: &str, any: bool, conds: &[Cond], acts: &[Act], folders: &[(String, String)],
    stop: bool, include_spam: bool, from: &str, until: &str) -> Result<Value, String> {
    if conds.is_empty() { return Err("Add a condition.".into()); }
    if acts.is_empty() { return Err("At least one action is required".into()); }
    let mut cj = vec![];
    for c in conds {
        let mut o = Map::new();
        o.insert("field".into(), json!(c.field));
        match c.field.as_str() {
            "all" => { o.insert("comparator".into(), json!("any")); o.insert("value".into(), json!("")); }
            "attachment" if c.cmp == "has_any" => { o.insert("comparator".into(), json!("has_any")); o.insert("value".into(), json!("")); }
            "size" => {
                let v = c.value.trim().to_uppercase().replace(' ', "");
                let digits = v.trim_end_matches(['K', 'M', 'G']);
                if digits.is_empty() || !digits.chars().all(|ch| ch.is_ascii_digit()) || v.len() - digits.len() > 1 { return Err(format!("\"{}\" is not a size (use e.g. 500K or 10M)", c.value.trim())); }
                o.insert("comparator".into(), json!(if c.cmp == "less_than" { "less_than" } else { "greater_than" }));
                o.insert("value".into(), json!(v));
            }
            _ => {
                if c.field == "header" {
                    if !header_ok(c.header.trim()) { return Err("Enter a header name (letters, digits and dashes)".into()); }
                    o.insert("headerName".into(), json!(c.header.trim()));
                }
                let cmp = if comparators(&c.field).contains(&c.cmp.as_str()) { c.cmp.clone() } else { comparators(&c.field).first().unwrap_or(&"contains").to_string() };
                // a regular expression is one value: commas in it are not separators
                let vals: Vec<String> = if cmp == "regex" { vec![c.value.trim().to_string()] } else { c.value.split(',').map(|v| v.trim().to_string()).filter(|v| !v.is_empty()).collect() };
                if cmp == "regex" && !vals[0].is_empty() {
                    if let Err(e) = regex::Regex::new(&vals[0]) { return Err(format!("\"{}\" is not a valid regular expression: {}", vals[0], e.to_string().lines().last().unwrap_or("").trim())); }
                }
                if vals.iter().all(|v| v.is_empty()) { return Err(format!("Add a value for \"{}\"", FIELDS.iter().find(|f| f.0 == c.field).map(|f| f.1).unwrap_or("the condition"))); }
                o.insert("comparator".into(), json!(cmp));
                o.insert("value".into(), if vals.len() == 1 { json!(vals[0]) } else { json!(vals) });
            }
        }
        cj.push(Value::Object(o));
    }
    let mut aj = vec![];
    for a in acts {
        let needs = ACTS.iter().find(|x| x.0 == a.kind).map(|x| x.2).unwrap_or("");
        let mut o = Map::new();
        o.insert("type".into(), json!(a.kind));
        match needs {
            "folder" => {
                let Some((id, path)) = folders.iter().find(|f| f.0 == a.mailbox) else { return Err("Select a folder for this action".into()) };
                o.insert("value".into(), json!(path));
                o.insert("mailboxId".into(), json!(id));
            }
            "tag" => { if a.value.trim().is_empty() { return Err("Select a tag for this action".into()); } o.insert("value".into(), json!(a.value.trim())); }
            "address" => {
                if !valid_email(a.value.trim()) { return Err("Enter an address to forward to".into()); }
                o.insert("value".into(), json!(a.value.trim()));
                if a.keep_copy { o.insert("keepCopy".into(), json!(true)); }
            }
            "text" => { if a.value.trim().is_empty() { return Err("Enter the rejection message".into()); } o.insert("value".into(), json!(a.value.trim())); }
            _ => {}
        }
        aj.push(Value::Object(o));
    }
    let mut r = if base.is_object() { base.clone() } else { json!({}) };
    let id = id.map(String::from).or_else(|| base["id"].as_str().map(String::from)).unwrap_or_else(|| {
        let mut b = [0u8; 6];
        let _ = getrandom::getrandom(&mut b);
        format!("bw-{}", b.iter().map(|x| format!("{x:02x}")).collect::<String>())
    });
    r["id"] = json!(id);
    r["name"] = json!(if name.trim().is_empty() { "Rule" } else { name.trim() });
    if r.get("enabled").is_none() { r["enabled"] = json!(true); }
    r["matchType"] = json!(if any { "any" } else { "all" });
    r["conditions"] = json!(cj);
    r["actions"] = json!(aj);
    r["stopProcessing"] = json!(stop);
    let o = r.as_object_mut().unwrap();
    if include_spam { o.insert("includeSpam".into(), json!(true)); } else { o.remove("includeSpam"); }
    let f = crate::sieve::day_boundary(from, false)?;
    let u = crate::sieve::day_boundary(until, true)?;
    if let (Some(f), Some(u)) = (&f, &u) { if u <= f { return Err("The period ends before it starts.".into()); } }
    match f { Some(f) => { o.insert("activeFrom".into(), json!(f)); } None => { o.remove("activeFrom"); } }
    match u { Some(u) => { o.insert("activeUntil".into(), json!(u)); } None => { o.remove("activeUntil"); } }
    Ok(r)
}

/// "From contains a@b, c@d and Subject is not X → Move to folder Newsletters, Mark as read"
pub fn summary(r: &Value) -> String {
    let join = if r["matchType"] == "any" { " or " } else { " and " };
    let conds: Vec<String> = conds_of(r).iter().map(|c| {
        let f = FIELDS.iter().find(|x| x.0 == c.field).map(|x| x.1).unwrap_or("If");
        match c.field.as_str() {
            "all" => "Every message".to_string(),
            "header" => format!("{} {} {}", c.header, cmp_label(&c.cmp), c.value),
            "attachment" if c.cmp == "has_any" => "Has an attachment".to_string(),
            _ => format!("{f} {} {}", cmp_label(&c.cmp), c.value),
        }
    }).collect();
    let acts: Vec<String> = acts_of(r).iter().map(|a| {
        let l = ACTS.iter().find(|x| x.0 == a.kind).map(|x| x.1).unwrap_or("act");
        if a.value.is_empty() { l.to_string() } else { format!("{l} {}", a.value) }
    }).collect();
    let mut s = format!("{} → {}", conds.join(join), acts.join(", "));
    if r["stopProcessing"] == true && !acts_of(r).iter().any(|a| a.kind == "stop") { s.push_str(" · then stop"); }
    if let Some(u) = r["activeUntil"].as_str() { s.push_str(&format!(" · until {}", &u[..10.min(u.len())])); }
    s
}

/// The rules with `id` moved one place up (-1) or down (+1).
pub fn moved(rules: &[Value], id: &str, dir: i32) -> Vec<Value> {
    let mut v = rules.to_vec();
    if let Some(i) = v.iter().position(|r| r["id"] == id) {
        let j = i as i64 + dir as i64;
        if j >= 0 && (j as usize) < v.len() { v.swap(i, j as usize); }
    }
    v
}

// ---------------- run on existing mail (lib/filters/retroactive.ts) ----------------

const TEXT_CMPS: [&str; 9] = ["contains", "not_contains", "is", "not_is", "starts_with", "ends_with", "matches", "address_is", "domain_is"];
const ADDRESS_HEADERS: [&str; 12] = ["from", "sender", "reply-to", "to", "cc", "bcc", "resent-from", "resent-sender", "resent-reply-to", "resent-to", "resent-cc", "resent-bcc"];
const RAW_ONLY: [&str; 16] = ["date", "resent-date", "message-id", "resent-message-id", "in-reply-to", "references", "return-path", "received",
    "list-help", "list-unsubscribe", "list-subscribe", "list-post", "list-owner", "list-archive", "list-id-raw", "x-none"];

fn cond_header(c: &Value) -> Option<String> {
    match c["field"].as_str()? {
        "header" => c["headerName"].as_str().map(str::trim).filter(|h| header_ok(h)).map(String::from),
        "from" => Some("From".into()), "to" => Some("To".into()), "cc" => Some("Cc".into()), "subject" => Some("Subject".into()),
        _ => None,
    }
}

fn address_test(c: &Value) -> bool {
    matches!(c["comparator"].as_str(), Some("address_is" | "domain_is")) && matches!(c["field"].as_str(), Some("from" | "to" | "cc"))
}

/// Why a rule cannot run over existing mail, or None when it can.
pub fn retro_unsupported(r: &Value) -> Option<&'static str> {
    if r.get("activeFrom").is_some() || r.get("activeUntil").is_some() { return Some("This rule only acts on mail arriving in its active period, so it says nothing about mail you already have."); }
    let conds = r["conditions"].as_array().cloned().unwrap_or_default();
    if conds.is_empty() { return Some("This rule has no conditions."); }
    for c in &conds {
        if !c["comparator"].as_str().is_some_and(|x| TEXT_CMPS.contains(&x)) || cond_header(c).is_none() {
            return Some("Body, size, attachment and regex conditions can only be checked by the server as mail arrives.");
        }
    }
    let acts = r["actions"].as_array().cloned().unwrap_or_default();
    let applied = |t: &str| matches!(t, "move" | "copy" | "mark_read" | "star" | "add_label");
    if !acts.iter().any(|a| a["type"].as_str().is_some_and(applied)) { return Some("None of this rule's actions changes a message that is already delivered."); }
    for a in &acts {
        let t = a["type"].as_str().unwrap_or("");
        if !applied(t) && t != "stop" { return Some("Forward, reject, discard and keep never run on mail you already have."); }
        if (t == "move" || t == "copy") && !a["mailboxId"].is_string() { return Some("Pick the folder again in the rule (it is only known by its name)."); }
        if t == "add_label" && a["value"].as_str().is_none_or(str::is_empty) { return Some("The tag action has no tag."); }
    }
    None
}

fn ascii_lower(s: &str) -> String { s.chars().map(|c| c.to_ascii_lowercase()).collect() }

/// RFC 5228 :matches (`*`, `?`, `\` escapes), on ASCII-folded text.
pub fn sieve_matches(pattern: &str, text: &str) -> bool {
    let p: Vec<char> = pattern.chars().collect();
    let t: Vec<char> = text.chars().collect();
    // tokens: Some(c) literal, None-star = '*', '?' handled as any one
    #[derive(Clone, Copy, PartialEq)]
    enum Tok { Lit(char), Any, Star }
    let mut toks = vec![];
    let mut i = 0;
    while i < p.len() {
        match p[i] { '\\' if i + 1 < p.len() => { toks.push(Tok::Lit(p[i + 1])); i += 2; continue; } '*' => toks.push(Tok::Star), '?' => toks.push(Tok::Any), c => toks.push(Tok::Lit(c)) }
        i += 1;
    }
    let (n, m) = (toks.len(), t.len());
    let mut dp = vec![vec![false; m + 1]; n + 1];
    dp[0][0] = true;
    for a in 1..=n {
        if toks[a - 1] == Tok::Star { dp[a][0] = dp[a - 1][0]; }
        for b in 1..=m {
            dp[a][b] = match toks[a - 1] { Tok::Star => dp[a - 1][b] || dp[a][b - 1], Tok::Any => dp[a - 1][b - 1], Tok::Lit(c) => dp[a - 1][b - 1] && c == t[b - 1] };
        }
    }
    dp[n][m]
}

fn text_matches(cmp: &str, key: &str, subject: &str) -> bool {
    let (k, s) = (ascii_lower(key), ascii_lower(subject));
    match cmp {
        "is" | "not_is" => s == k,
        "starts_with" => sieve_matches(&format!("{k}*"), &s),
        "ends_with" => sieve_matches(&format!("*{k}"), &s),
        "matches" => sieve_matches(&k, &s),
        _ => s.contains(&k),
    }
}

fn vals(v: &Value) -> Vec<String> {
    match v { Value::Array(a) => a.iter().filter_map(|x| x.as_str()).filter(|x| !x.is_empty()).map(String::from).collect(), Value::String(s) if !s.is_empty() => vec![s.clone()], _ => vec![] }
}

/// A message as the retroactive pass sees it: mailboxIds, keywords, from/to/cc, and
/// lower-cased header name → occurrences.
pub fn cond_matches(c: &Value, m: &Value) -> bool {
    let vs = vals(&c["value"]);
    if vs.is_empty() { return false; }
    if address_test(c) {
        let addrs: Vec<String> = m[c["field"].as_str().unwrap_or("from")].as_array().map(|a| a.iter().filter_map(|x| x["email"].as_str()).map(|e| e.trim().to_string()).filter(|e| !e.is_empty()).collect()).unwrap_or_default();
        let parts: Vec<String> = if c["comparator"] == "domain_is" { addrs.iter().map(|a| a.rsplit_once('@').map(|x| x.1.to_string()).unwrap_or_default()).collect() } else { addrs };
        return parts.iter().any(|p| vs.iter().any(|v| ascii_lower(v) == ascii_lower(p)));
    }
    let h = cond_header(c).map(|h| h.to_lowercase()).unwrap_or_default();
    let occ: Vec<String> = m["headers"][&h].as_array().map(|a| a.iter().filter_map(|x| x.as_str().map(String::from)).collect()).unwrap_or_default();
    let cmp = match c["comparator"].as_str().unwrap_or("contains") { "address_is" | "domain_is" => "contains", x => x };
    let pos = occ.iter().any(|o| vs.iter().any(|v| text_matches(cmp, v, o)));
    if cmp == "not_contains" || cmp == "not_is" { !pos } else { pos }
}

pub fn rule_matches(r: &Value, m: &Value) -> bool {
    let conds = r["conditions"].as_array().cloned().unwrap_or_default();
    if conds.is_empty() { return false; }
    let res: Vec<bool> = conds.iter().map(|c| cond_matches(c, m)).collect();
    let ok = if r["matchType"] == "any" { res.iter().any(|x| *x) } else { res.iter().all(|x| *x) };
    let skips_spam = r["includeSpam"] != true && r["actions"].as_array().is_some_and(|a| a.iter().any(|x| matches!(x["type"].as_str(), Some("move" | "copy"))));
    ok && !(skips_spam && m["keywords"]["$junk"] == true)
}

/// Email/query filter: a superset of what the rule matches in the mailbox (only exact
/// address and domain conditions narrow it).
pub fn query_filter(r: &Value, mailbox: &str) -> Value {
    let conds = r["conditions"].as_array().cloned().unwrap_or_default();
    let narrow = |c: &Value| -> Option<Value> {
        if !address_test(c) { return None; }
        let vs = vals(&c["value"]);
        if vs.is_empty() { return None; }
        let f = c["field"].as_str().unwrap_or("from");
        let each: Vec<Value> = vs.iter().map(|v| json!({ f: v })).collect();
        Some(if each.len() == 1 { each[0].clone() } else { json!({"operator": "OR", "conditions": each}) })
    };
    let narrowed: Vec<Option<Value>> = conds.iter().map(narrow).collect();
    let inbox = json!({"inMailbox": mailbox});
    if r["matchType"] == "any" {
        if narrowed.is_empty() || narrowed.iter().any(|n| n.is_none()) { return inbox; }
        let parts: Vec<Value> = narrowed.into_iter().flatten().collect();
        return json!({"operator": "AND", "conditions": [inbox, if parts.len() == 1 { parts[0].clone() } else { json!({"operator": "OR", "conditions": parts}) }]});
    }
    let parts: Vec<Value> = narrowed.into_iter().flatten().collect();
    if parts.is_empty() { inbox } else { let mut all = vec![inbox]; all.extend(parts); json!({"operator": "AND", "conditions": all}) }
}

pub fn retro_properties(r: &Value) -> Vec<String> {
    let mut p = vec!["mailboxIds".to_string(), "keywords".to_string()];
    for c in r["conditions"].as_array().cloned().unwrap_or_default() {
        if address_test(&c) { p.push(c["field"].as_str().unwrap_or("from").into()); continue; }
        let Some(h) = cond_header(&c) else { continue };
        let l = h.to_lowercase();
        if ADDRESS_HEADERS.contains(&l.as_str()) { p.push(format!("header:{h}:asAddresses:all")); }
        else if RAW_ONLY.contains(&l.as_str()) { p.push(format!("header:{h}:all")); }
        else { p.push(format!("header:{h}:asText:all")); p.push(format!("header:{h}:all")); }
    }
    p.dedup();
    p
}

fn unfold(v: &str) -> String { v.replace("\r\n", "").replace('\n', "").trim().to_string() }

/// An Email/get record (with retro_properties) as a message the matcher reads.
pub fn retro_message(rec: &Value) -> Value {
    let mut headers = Map::new();
    let list = |v: &Value| -> Vec<Value> { match v { Value::Array(a) => a.clone(), Value::Null => vec![], x => vec![x.clone()] } };
    if let Some(o) = rec.as_object() {
        for (k, v) in o {
            let Some(rest) = k.strip_prefix("header:") else { continue };
            if let Some(h) = rest.strip_suffix(":asAddresses:all") {
                let occ: Vec<Value> = list(v).iter().map(|l| json!(list(l).iter().filter_map(|a| {
                    let (n, e) = (a["name"].as_str().unwrap_or(""), a["email"].as_str().unwrap_or(""));
                    if e.is_empty() { (!n.is_empty()).then(|| n.to_string()) } else if n.is_empty() { Some(e.to_string()) } else { Some(format!("{n} <{e}>")) }
                }).collect::<Vec<_>>().join(", "))).collect();
                headers.insert(h.to_lowercase(), json!(occ));
            } else if let Some(h) = rest.strip_suffix(":asText:all") {
                let raw = list(&rec[format!("header:{h}:all")]);
                let occ: Vec<Value> = list(v).iter().enumerate().filter_map(|(i, t)| t.as_str().map(String::from).or_else(|| raw.get(i).and_then(|r| r.as_str()).map(unfold))).map(Value::from).collect();
                headers.insert(h.to_lowercase(), json!(occ));
            } else if let Some(h) = rest.strip_suffix(":all") {
                if o.contains_key(&format!("header:{h}:asText:all")) { continue; }
                headers.insert(h.to_lowercase(), json!(list(v).iter().filter_map(|x| x.as_str()).map(unfold).collect::<Vec<_>>()));
            }
        }
    }
    json!({"id": rec["id"], "mailboxIds": rec["mailboxIds"], "keywords": rec["keywords"], "from": rec["from"], "to": rec["to"], "cc": rec["cc"], "headers": headers})
}

/// (kind, ids, arg) steps in Sieve's order: flags first, then the first move, then copies.
pub fn plan(r: &Value, msgs: &[Value]) -> Vec<(String, Vec<String>, String)> {
    if retro_unsupported(r).is_some() { return vec![]; }
    let matched: Vec<&Value> = msgs.iter().filter(|m| rule_matches(r, m)).collect();
    let id = |m: &&Value| m["id"].as_str().unwrap_or("").to_string();
    let mut steps = vec![];
    let acts = r["actions"].as_array().cloned().unwrap_or_default();
    for a in acts.iter().filter(|a| matches!(a["type"].as_str(), Some("mark_read" | "star" | "add_label"))) {
        let kw = match a["type"].as_str() { Some("mark_read") => "$seen".to_string(), Some("star") => "$flagged".into(), _ => format!("$label:{}", a["value"].as_str().unwrap_or("")) };
        let ids: Vec<String> = matched.iter().filter(|m| m["keywords"][&kw] != true).map(id).collect();
        if !ids.is_empty() { steps.push(("keyword".to_string(), ids, kw)); }
    }
    let files: Vec<&Value> = acts.iter().filter(|a| matches!(a["type"].as_str(), Some("move" | "copy")) && a["mailboxId"].is_string()).collect();
    let first_move = files.iter().position(|a| a["type"] == "move");
    let not_in = |mb: &str| -> Vec<String> { matched.iter().filter(|m| m["mailboxIds"][mb] != true).map(id).collect() };
    if let Some(i) = first_move { let mb = files[i]["mailboxId"].as_str().unwrap().to_string(); let ids = not_in(&mb); if !ids.is_empty() { steps.push(("move".into(), ids, mb)); } }
    for (i, a) in files.iter().enumerate() {
        if Some(i) == first_move { continue; }
        let mb = a["mailboxId"].as_str().unwrap().to_string();
        let ids = not_in(&mb);
        if !ids.is_empty() { steps.push(("copy".into(), ids, mb)); }
    }
    steps
}

pub fn plan_count(steps: &[(String, Vec<String>, String)]) -> usize {
    let mut s: std::collections::HashSet<&String> = Default::default();
    for (_, ids, _) in steps { s.extend(ids.iter()); }
    s.len()
}

fn ptr(k: &str) -> String { k.replace('~', "~0").replace('/', "~1") }

/// The Email/set patch for one plan step (move replaces the folders, as Sieve's fileinto does).
pub fn step_patch(kind: &str, arg: &str) -> Value {
    match kind {
        "keyword" => json!({ format!("keywords/{}", ptr(arg)): true }),
        "move" => json!({"mailboxIds": { arg: true }}),
        _ => json!({ format!("mailboxIds/{}", ptr(arg)): true }),
    }
}

#[derive(Debug, PartialEq)]
pub enum Applied { Done(usize), Stale(usize), Failed(usize, String) }

/// Apply the plan in Email/set calls of at most `max` updates, each guarded by `ifInState`
/// (RFC 8620 §5.3) chained from the previous call's newState. `send` posts one method call
/// and returns its [name, args] response. Counts updated messages; stops on the first error.
pub fn apply_with(mut send: impl FnMut(Value) -> Result<Value, String>, account: &str, mut state: String,
    steps: &[(String, Vec<String>, String)], max: usize) -> Applied {
    let mut done: std::collections::HashSet<String> = Default::default();
    let mut bad = vec![];
    for (kind, ids, arg) in steps {
        let patch = step_patch(kind, arg);
        for chunk in ids.chunks(max.max(1)) {
            let upd: Map<String, Value> = chunk.iter().map(|i| (i.clone(), patch.clone())).collect();
            let mut a = json!({"accountId": account, "update": upd});
            if !state.is_empty() { a["ifInState"] = json!(state); }
            let r = match send(json!(["Email/set", a, "a"])) { Ok(r) => r, Err(e) => return Applied::Failed(done.len(), e) };
            if r[0] == "error" {
                if r[1]["type"] == "stateMismatch" { return Applied::Stale(done.len()); }
                return Applied::Failed(done.len(), crate::jmap::method_error(&r[1]));
            }
            if let Some(o) = r[1]["updated"].as_object() { done.extend(o.keys().cloned()); }
            if let Some(nu) = r[1]["notUpdated"].as_object() { bad.extend(nu.iter().map(|(id, e)| format!("{id}: {}", e["type"].as_str().unwrap_or("error")))); }
            state = r[1]["newState"].as_str().unwrap_or("").to_string();
        }
    }
    if bad.is_empty() { Applied::Done(done.len()) } else { Applied::Failed(done.len(), bad.join("; ")) }
}

/// Whether a scan's result still belongs to the open dialog (no later run started).
pub fn current(now: u64, gen: u64, open: bool) -> bool { open && now == gen }

pub fn applied_text(r: &Applied, total: usize) -> String {
    let s = |n: usize| if n == 1 { "" } else { "s" };
    match r {
        Applied::Done(n) => format!("Rule applied to {n} message{}", s(*n)),
        Applied::Stale(0) => "Your mail changed since the check; nothing was applied. Run the rule again.".into(),
        Applied::Stale(n) => format!("Applied to {n} of {total} message{}; your mail changed meanwhile, run the rule again for the rest.", s(total)),
        Applied::Failed(n, e) => format!("Applied to {n} of {total} message{}: {e}", s(total)),
    }
}

// ---------------- UI ----------------

fn render(u: &AppWindow) {
    let g = u.global::<FilterX>();
    let ext = sieve_ext();
    ED.with(|e| {
        let e = e.borrow();
        let conds: Vec<FCond> = e.conds.iter().map(|c| {
            let cmps = comparators(&c.field);
            let vk = match c.field.as_str() { "all" => "", "size" => "size", "attachment" => if c.cmp == "has_type" { "types" } else { "" }, _ => "text" };
            FCond { field: FIELDS.iter().position(|f| f.0 == c.field).unwrap_or(0) as i32, cmp: cmps.iter().position(|x| *x == c.cmp).unwrap_or(0) as i32,
                cmps: model(cmps.iter().map(|x| sv(cmp_label(x))).collect()), value: sv(&c.value), header: sv(&c.header), value_kind: sv(vk), is_header: c.field == "header" }
        }).collect();
        let acts: Vec<FAct> = e.acts.iter().map(|a| {
            let (i, needs) = ACTS.iter().enumerate().find(|(_, x)| x.0 == a.kind).map(|(i, x)| (i, x.2)).unwrap_or((0, "folder"));
            let offer = offered_acts(&ext, &a.kind);
            FAct { kind: offer.iter().position(|&j| j == i).unwrap_or(0) as i32, value: sv(&a.value),
                folder: e.folders.iter().position(|f| f.0 == a.mailbox).map(|x| x as i32).unwrap_or(-1), keep_copy: a.keep_copy, needs: sv(needs),
                types: model(offer.iter().map(|&j| sv(ACTS[j].1)).collect()) }
        }).collect();
        g.set_conds(model(conds));
        g.set_acts(model(acts));
        g.set_folders(model(e.folders.iter().map(|f| sv(&f.1)).collect()));
    });
}

fn open_editor(u: &AppWindow, cache: &Cache, id: Option<&str>) {
    let k = cache.lock().unwrap();
    let rule = id.and_then(|i| k.rules.iter().find(|r| r["id"] == i).cloned());
    let folders = folder_paths(&k.mailboxes);
    let ext = k.sieve_ext.clone();
    drop(k);
    let g = u.global::<FilterX>();
    g.set_fields(model(FIELDS.iter().map(|f| sv(f.1)).collect()));
    let base = rule.clone().unwrap_or(Value::Null);
    g.set_title(if rule.is_some() { "Edit rule".into() } else { "New rule".into() });
    g.set_name(base["name"].as_str().unwrap_or("").into());
    g.set_match_type(if base["matchType"] == "any" { 1 } else { 0 });
    g.set_stop(base["stopProcessing"] == true);
    g.set_include_spam(base["includeSpam"] == true);
    let local_day = |v: &Value| v.as_str().and_then(|s| chrono::DateTime::parse_from_rfc3339(s).ok()).map(|t| t.with_timezone(&chrono::Local).format("%Y-%m-%d").to_string()).unwrap_or_default();
    g.set_from(local_day(&base["activeFrom"]).into());
    g.set_until(local_day(&base["activeUntil"]).into());
    g.set_status("".into());
    // G-020: a rule that uses an action the server does not list still shows and saves as it is
    let unsupported: Vec<&str> = crate::sieve::unsupported_actions(&base, &ext).iter()
        .map(|k| ACTS.iter().find(|a| a.0 == k.as_str()).map(|a| a.1).unwrap_or("an unknown action")).collect::<Vec<_>>();
    if !unsupported.is_empty() {
        g.set_status(format!("This rule uses {}, which this server does not list as a Sieve extension. The rule is kept as it is; the server may refuse the script when you save.", unsupported.join(", ")).into());
    }
    g.set_busy(false);
    let mut conds = conds_of(&base);
    let mut acts = acts_of(&base);
    // a rule whose folder is known only by name: find it by path
    for a in acts.iter_mut().filter(|a| (a.kind == "move" || a.kind == "copy") && a.mailbox.is_empty()) {
        if let Some(f) = folders.iter().find(|f| f.1.eq_ignore_ascii_case(&a.value)) { a.mailbox = f.0.clone(); }
    }
    if conds.is_empty() { conds.push(Cond { field: "from".into(), cmp: "contains".into(), ..Default::default() }); }
    if acts.is_empty() { acts.push(Act { kind: "move".into(), ..Default::default() }); }
    ED.with(|e| *e.borrow_mut() = Ed { id: rule.as_ref().and_then(|r| r["id"].as_str().map(String::from)), base, conds, acts, folders });
    render(u);
    g.set_open(true);
}

/// Write the rules (with the script's metadata kept) in the background, then reload the page.
fn save_rules(u: &AppWindow, c: Arc<Client>, cache: Cache, reload: Reload, rules: Vec<Value>, before: Vec<Value>, done: &'static str, close: bool) {
    let (script, scripts) = {
        let k = cache.lock().unwrap();
        (crate::sieve::generate_meta(&crate::sieve::with_rules(&k.filter_meta, &rules), &k.external, &k.sieve_ext), k.scripts.clone())
    };
    let w = u.as_weak();
    u.global::<FilterX>().set_busy(true);
    std::thread::spawn(move || {
        let res = crate::server_settings::save_script(&c, &script, &scripts);
        { let mut k = cache.lock().unwrap(); if res.is_ok() { k.rules = rules; } else { k.rules = before; } }
        let ok = res.is_ok();
        let _ = w.upgrade_in_event_loop(move |u| {
            let g = u.global::<FilterX>();
            g.set_busy(false);
            match res {
                Ok(()) => { if close { g.set_open(false); } crate::mail::show_toast(&u, done, false); }
                Err(e) => { if close { g.set_status(e.clone().into()); } else { crate::mail::show_toast(&u, &e, false); } }
            }
            // on failure the cache is back to the server's list; reload only shows what was saved
            if ok { reload("filters".into()); } else if !close { reload("filters".into()); }
        });
    });
}

fn run_rule(u: &AppWindow, c: Arc<Client>, cache: &Cache, id: &str) {
    let Some(rule) = cache.lock().unwrap().rules.iter().find(|r| r["id"] == id).cloned() else { return };
    let g = u.global::<FilterX>();
    g.set_retro_title(format!("Run \"{}\" on existing mail", rule["name"].as_str().unwrap_or("Rule")).into());
    g.set_retro_can_apply(false);
    g.set_retro_busy(false);
    g.set_retro_open(true);
    let gen = RETRO.with(|r| { let mut r = r.borrow_mut(); let gen = r.gen + 1; *r = Retro { gen, ..Default::default() }; gen });
    if let Some(why) = retro_unsupported(&rule) { g.set_retro_text(why.into()); return; }
    g.set_retro_text("Looking through your Inbox…".into());
    let w = u.as_weak();
    std::thread::spawn(move || {
        let rule2 = rule.clone();
        let res: Result<(Vec<(String, Vec<String>, String)>, String), String> = (|| {
            // the Email state before looking: Apply sends it as ifInState, so nothing changed in between
            let st = c.call(json!([["Email/get", {"accountId": c.account, "ids": []}, "s"]]))?;
            let state = st[0][1]["state"].as_str().unwrap_or("").to_string();
            let inbox = c.role_ids()?.get("inbox").cloned().ok_or("No Inbox")?;
            let ids = c.query_all("Email/query", &c.account, json!({"filter": query_filter(&rule, &inbox)}))?;
            let props = json!(retro_properties(&rule).into_iter().chain(["id".to_string()]).collect::<Vec<_>>());
            let recs = c.get_all("Email/get", &c.account, &ids, Some(&props))?;
            let msgs: Vec<Value> = recs.iter().map(retro_message).collect();
            Ok((plan(&rule, &msgs), state))
        })();
        let _ = w.upgrade_in_event_loop(move |u| {
            let g = u.global::<FilterX>();
            // a later run (or a closed dialog) owns the dialog now: drop this result
            if !current(RETRO.with(|r| r.borrow().gen), gen, g.get_retro_open()) { return; }
            match res {
                Ok((steps, state)) => {
                    let n = plan_count(&steps);
                    g.set_retro_text(if n == 0 { "No message in your Inbox would change.".into() } else {
                        format!("{n} message{} in your Inbox match{} and would be changed as the rule says. Forward, reject and discard never run on old mail.", if n == 1 { "" } else { "s" }, if n == 1 { "es" } else { "" }).into()
                    });
                    g.set_retro_can_apply(n > 0);
                    RETRO.with(|r| *r.borrow_mut() = Retro { rule: rule2, plan: steps, gen, state });
                }
                Err(e) => g.set_retro_text(format!("Could not check your Inbox: {e}").into()),
            }
        });
    });
}

/// Automation probe: the loaded rules, the editor and the script (read-only).
pub fn probe(u: &AppWindow) -> String {
    let g = u.global::<FilterX>();
    let (rules, script) = CACHE.with(|c| c.borrow().as_ref().map(|k| { let k = k.lock().unwrap(); (k.rules.clone(), k.script_text.clone()) })).unwrap_or_default();
    json!({"rules": rules.iter().map(|r| json!([r["id"], r["name"], r["enabled"], summary(r)])).collect::<Vec<_>>(), "script": script,
        "editor": {"open": g.get_open(), "status": g.get_status().to_string(), "conds": ED.with(|e| e.borrow().conds.len()), "acts": ED.with(|e| e.borrow().acts.len())},
        "retro": {"open": g.get_retro_open(), "text": g.get_retro_text().to_string(), "can": g.get_retro_can_apply()}}).to_string()
}

pub fn wire(ui: &AppWindow, st: ClientSlot, cache: Cache, reload: Reload) {
    CACHE.with(|c| *c.borrow_mut() = Some(cache.clone()));
    let g = ui.global::<FilterX>();
    let client = |st: &ClientSlot| st.lock().unwrap().clone();
    let (w, k) = (ui.as_weak(), cache.clone());
    g.on_new_rule(move || open_editor(&w.unwrap(), &k, None));
    let (w, k) = (ui.as_weak(), cache.clone());
    g.on_edit(move |id| open_editor(&w.unwrap(), &k, Some(&id)));
    let w = ui.as_weak();
    g.on_add_cond(move || { ED.with(|e| e.borrow_mut().conds.push(Cond { field: "from".into(), cmp: "contains".into(), ..Default::default() })); render(&w.unwrap()); });
    let w = ui.as_weak();
    g.on_remove_cond(move |i| { ED.with(|e| { let mut e = e.borrow_mut(); if e.conds.len() > 1 && (i as usize) < e.conds.len() { e.conds.remove(i as usize); } }); render(&w.unwrap()); });
    g.on_set_cond(move |i, part, v| ED.with(|e| if let Some(c) = e.borrow_mut().conds.get_mut(i as usize) { if part == "header" { c.header = v.into(); } else { c.value = v.into(); } }));
    let w = ui.as_weak();
    g.on_set_cond_field(move |i, f| {
        ED.with(|e| if let Some(c) = e.borrow_mut().conds.get_mut(i as usize) {
            c.field = FIELDS.get(f as usize).map(|x| x.0).unwrap_or("from").into();
            if !comparators(&c.field).contains(&c.cmp.as_str()) { c.cmp = comparators(&c.field).first().copied().unwrap_or("any").into(); }
        });
        render(&w.unwrap());
    });
    let w = ui.as_weak();
    g.on_set_cond_cmp(move |i, x| { ED.with(|e| if let Some(c) = e.borrow_mut().conds.get_mut(i as usize) { if let Some(cmp) = comparators(&c.field).get(x as usize) { c.cmp = cmp.to_string(); } }); render(&w.unwrap()); });
    let w = ui.as_weak();
    g.on_add_act(move || { ED.with(|e| e.borrow_mut().acts.push(Act { kind: "mark_read".into(), ..Default::default() })); render(&w.unwrap()); });
    let w = ui.as_weak();
    g.on_remove_act(move |i| { ED.with(|e| { let mut e = e.borrow_mut(); if e.acts.len() > 1 && (i as usize) < e.acts.len() { e.acts.remove(i as usize); } }); render(&w.unwrap()); });
    let w = ui.as_weak();
    g.on_set_act_kind(move |i, x| {
        // x is a position in the row's own offer list (see render)
        let ext = sieve_ext();
        ED.with(|e| if let Some(a) = e.borrow_mut().acts.get_mut(i as usize) {
            let offer = offered_acts(&ext, &a.kind);
            a.kind = offer.get(x as usize).map(|&j| ACTS[j].0).unwrap_or("move").into();
        });
        render(&w.unwrap());
    });
    g.on_set_act_value(move |i, v| ED.with(|e| if let Some(a) = e.borrow_mut().acts.get_mut(i as usize) { a.value = v.into(); }));
    g.on_set_act_folder(move |i, f| ED.with(|e| { let mut e = e.borrow_mut(); let id = e.folders.get(f as usize).map(|x| x.0.clone()); if let (Some(a), Some(id)) = (e.acts.get_mut(i as usize), id) { a.mailbox = id; } }));
    g.on_set_act_keep(move |i, on| ED.with(|e| if let Some(a) = e.borrow_mut().acts.get_mut(i as usize) { a.keep_copy = on; }));
    let (w, s, k, rl) = (ui.as_weak(), st.clone(), cache.clone(), reload.clone());
    g.on_save(move || {
        let u = w.unwrap();
        let Some(c) = client(&s) else { return };
        let g = u.global::<FilterX>();
        let built = ED.with(|e| {
            let e = e.borrow();
            build_rule(&e.base, e.id.as_deref(), &g.get_name(), g.get_match_type() == 1, &e.conds, &e.acts, &e.folders, g.get_stop(), g.get_include_spam(), &g.get_from(), &g.get_until())
                .map(|r| (r, e.id.clone()))
        });
        match built {
            Err(e) => g.set_status(e.into()),
            Ok((rule, id)) => {
                let before = k.lock().unwrap().rules.clone();
                let mut rules = before.clone();
                match id.and_then(|id| rules.iter().position(|r| r["id"] == id.as_str())) { Some(i) => rules[i] = rule, None => rules.push(rule) }
                save_rules(&u, c, k.clone(), rl.clone(), rules, before, "Rule saved", true);
            }
        }
    });
    let (w, s, k, rl) = (ui.as_weak(), st.clone(), cache.clone(), reload.clone());
    g.on_move(move |id, dir| {
        let Some(c) = client(&s) else { return };
        let rules = k.lock().unwrap().rules.clone();
        let next = moved(&rules, &id, dir);
        if next.iter().map(|r| r["id"].clone()).eq(rules.iter().map(|r| r["id"].clone())) { return; }
        k.lock().unwrap().rules = next.clone();
        save_rules(&w.unwrap(), c, k.clone(), rl.clone(), next, rules, "Rule order saved", false);
    });
    let (w, s, k, rl) = (ui.as_weak(), st.clone(), cache.clone(), reload.clone());
    g.on_delete(move |id| {
        let u = w.unwrap();
        let g = u.global::<FilterX>();
        if g.get_confirm() != id { g.set_confirm(id); return; }
        g.set_confirm("".into());
        let Some(c) = client(&s) else { return };
        let before = k.lock().unwrap().rules.clone();
        let rules: Vec<Value> = before.iter().filter(|r| r["id"] != id.as_str()).cloned().collect();
        save_rules(&u, c, k.clone(), rl.clone(), rules, before, "Rule deleted", false);
    });
    let (w, s, k) = (ui.as_weak(), st.clone(), cache.clone());
    g.on_run(move |id| { if let Some(c) = client(&s) { run_rule(&w.unwrap(), c, &k, &id); } });
    let (w, s) = (ui.as_weak(), st.clone());
    g.on_retro_apply(move || {
        let u = w.unwrap();
        let Some(c) = client(&s) else { return };
        if !u.global::<FilterX>().get_retro_open() { return; }
        let (steps, state, rule) = RETRO.with(|r| { let r = r.borrow(); (r.plan.clone(), r.state.clone(), r.rule.clone()) });
        if steps.is_empty() || rule.is_null() { return; }
        let total = plan_count(&steps);
        u.global::<FilterX>().set_retro_busy(true);
        let w = u.as_weak();
        std::thread::spawn(move || {
            let acc = c.account.clone();
            let res = apply_with(|call| c.request(json!([call])).map(|mut v| v.pop().unwrap_or(Value::Null)), &acc, state, &steps, c.max_set());
            let _ = w.upgrade_in_event_loop(move |u| {
                let g = u.global::<FilterX>();
                g.set_retro_busy(false);
                g.set_retro_open(false);
                crate::mail::show_toast(&u, &applied_text(&res, total), false);
                RETRO.with(|r| { let gen = r.borrow().gen; *r.borrow_mut() = Retro { gen, ..Default::default() }; });
            });
        });
    });
}

#[cfg(test)]
mod tests {
    use super::*;

    fn folders() -> Vec<(String, String)> { vec![("i".into(), "INBOX".into()), ("n".into(), "News/Letters".into())] }

    #[test]
    fn builds_multi_condition_rule_and_round_trips() {
        let conds = vec![
            Cond { field: "from".into(), cmp: "domain_is".into(), value: "example.com, example.org".into(), ..Default::default() },
            Cond { field: "header".into(), cmp: "not_is".into(), value: "bulk".into(), header: "Precedence".into() },
            Cond { field: "size".into(), cmp: "greater_than".into(), value: "10m".into(), ..Default::default() },
            Cond { field: "subject".into(), cmp: "regex".into(), value: "^\\[(a|b),c\\]".into(), ..Default::default() },
        ];
        let acts = vec![Act { kind: "move".into(), mailbox: "n".into(), ..Default::default() }, Act { kind: "mark_read".into(), ..Default::default() },
            Act { kind: "forward".into(), value: "me@x.org".into(), keep_copy: true, ..Default::default() }];
        let r = build_rule(&Value::Null, None, "News", true, &conds, &acts, &folders(), true, false, "", "").unwrap();
        assert!(r["id"].as_str().unwrap().starts_with("bw-"));
        assert_eq!(r["matchType"], "any");
        assert_eq!(r["conditions"][0]["value"], json!(["example.com", "example.org"]));
        assert_eq!(r["conditions"][1]["headerName"], "Precedence");
        assert_eq!(r["conditions"][2]["value"], "10M");
        assert_eq!(r["conditions"][3]["value"], "^\\[(a|b),c\\]");
        assert_eq!(r["actions"][0]["value"], "News/Letters");
        assert_eq!(r["actions"][0]["mailboxId"], "n");
        assert_eq!(r["actions"][2]["keepCopy"], true);
        // the generator accepts it
        let script = crate::sieve::generate_meta(&json!({"version": 1, "rules": [r.clone()]}), "", &["regex".into()]);
        assert!(script.contains("anyof(address :domain :is \"From\" [\"example.com\", \"example.org\"], not header :is \"Precedence\" \"bulk\", size :over 10M, header :regex \"Subject\""), "{script}");
        assert!(script.contains("fileinto \"News/Letters\";"));
        assert!(script.contains("redirect :copy \"me@x.org\";"));
        // back into the form
        let c2 = conds_of(&r);
        assert_eq!(c2[0].value, "example.com, example.org");
        assert_eq!(acts_of(&r)[0].mailbox, "n");
        // editing keeps unknown properties and the id
        let mut base = r.clone();
        base["origin"] = json!("bulwark");
        let r2 = build_rule(&base, None, "News 2", false, &c2[..1], &acts_of(&r)[..1], &folders(), false, true, "", "").unwrap();
        assert_eq!(r2["id"], r["id"]);
        assert_eq!(r2["origin"], "bulwark");
        assert_eq!(r2["includeSpam"], true);
        assert_eq!(r2["matchType"], "all");
    }

    #[test]
    fn validation() {
        let f = folders();
        let c = vec![Cond { field: "from".into(), cmp: "contains".into(), value: "".into(), ..Default::default() }];
        let a = vec![Act { kind: "mark_read".into(), ..Default::default() }];
        assert!(build_rule(&Value::Null, None, "", false, &c, &a, &f, false, false, "", "").is_err());
        let c = vec![Cond { field: "all".into(), ..Default::default() }];
        assert!(build_rule(&Value::Null, None, "", false, &c, &a, &f, false, false, "", "").is_ok());
        assert!(build_rule(&Value::Null, None, "", false, &c, &[Act { kind: "move".into(), ..Default::default() }], &f, false, false, "", "").is_err());
        assert!(build_rule(&Value::Null, None, "", false, &c, &[Act { kind: "forward".into(), value: "nope".into(), ..Default::default() }], &f, false, false, "", "").is_err());
        assert!(build_rule(&Value::Null, None, "", false, &c, &[Act { kind: "reject".into(), ..Default::default() }], &f, false, false, "", "").is_err());
        let h = vec![Cond { field: "header".into(), cmp: "contains".into(), value: "x".into(), header: "Bad Header".into() }];
        assert!(build_rule(&Value::Null, None, "", false, &h, &a, &f, false, false, "", "").is_err());
        let s = vec![Cond { field: "size".into(), cmp: "less_than".into(), value: "lots".into(), ..Default::default() }];
        assert!(build_rule(&Value::Null, None, "", false, &s, &a, &f, false, false, "", "").is_err());
        assert!(build_rule(&Value::Null, None, "", false, &c, &a, &f, false, false, "2026-05-02", "2026-05-01").is_err());
        let p = build_rule(&Value::Null, None, "", false, &c, &a, &f, false, false, "2026-05-01", "").unwrap();
        assert!(p["activeFrom"].is_string());
        assert!(p.get("activeUntil").is_none());
    }

    #[test]
    fn reorder_and_summary() {
        let rules = vec![json!({"id": "a"}), json!({"id": "b"}), json!({"id": "c"})];
        let ids = |v: Vec<Value>| v.iter().map(|r| r["id"].as_str().unwrap().to_string()).collect::<Vec<_>>().join("");
        assert_eq!(ids(moved(&rules, "b", -1)), "bac");
        assert_eq!(ids(moved(&rules, "c", 1)), "abc");
        assert_eq!(ids(moved(&rules, "a", 1)), "bac");
        let r = json!({"matchType": "any", "conditions": [{"field": "from", "comparator": "contains", "value": "x"}, {"field": "attachment", "comparator": "has_any", "value": ""}],
            "actions": [{"type": "star"}, {"type": "move", "value": "Archive"}], "stopProcessing": true});
        assert_eq!(summary(&r), "From contains x or Has an attachment → Star message, Move to folder Archive · then stop");
    }

    #[test]
    fn sieve_match_semantics() {
        assert!(sieve_matches("news*", "newsletter"));
        assert!(sieve_matches("*@example.com", "a@example.com"));
        assert!(sieve_matches("a?c", "abc"));
        assert!(!sieve_matches("a?c", "ac"));
        assert!(sieve_matches("a\\*b", "a*b"));
        assert!(!sieve_matches("a\\*b", "axb"));
    }

    #[test]
    fn retroactive_plan() {
        let rule = json!({"matchType": "all", "conditions": [{"field": "from", "comparator": "domain_is", "value": "news.com"}, {"field": "subject", "comparator": "not_contains", "value": "urgent"}],
            "actions": [{"type": "mark_read"}, {"type": "move", "value": "News", "mailboxId": "n"}, {"type": "copy", "value": "Keep", "mailboxId": "k"}]});
        assert!(retro_unsupported(&rule).is_none());
        let q = query_filter(&rule, "inbox");
        assert_eq!(q, json!({"operator": "AND", "conditions": [{"inMailbox": "inbox"}, {"from": "news.com"}]}));
        let props = retro_properties(&rule);
        assert!(props.contains(&"from".to_string()) && props.contains(&"header:Subject:asText:all".to_string()));
        let rec = |id: &str, from: &str, subj: &str, kw: Value, mb: Value| retro_message(&json!({"id": id, "from": [{"email": from}], "mailboxIds": mb, "keywords": kw,
            "header:Subject:asText:all": [subj], "header:Subject:all": [format!(" {subj}")]}));
        let msgs = vec![
            rec("1", "a@news.com", "Weekly", json!({}), json!({"inbox": true})),
            rec("2", "b@NEWS.com", "URGENT stuff", json!({}), json!({"inbox": true})),
            rec("3", "c@news.com", "Monthly", json!({"$seen": true}), json!({"inbox": true})),
            rec("4", "d@other.com", "Weekly", json!({}), json!({"inbox": true})),
            rec("5", "e@news.com", "Spam", json!({"$junk": true}), json!({"inbox": true})),
        ];
        let steps = plan(&rule, &msgs);
        assert_eq!(steps[0], ("keyword".to_string(), vec!["1".to_string()], "$seen".to_string()));
        assert_eq!(steps[1].0, "move");
        assert_eq!(steps[1].1, vec!["1".to_string(), "3".to_string()]);
        assert_eq!(steps[2].0, "copy");
        assert_eq!(plan_count(&steps), 2);
        // unsupported shapes
        assert!(retro_unsupported(&json!({"conditions": [{"field": "body", "comparator": "contains", "value": "x"}], "actions": [{"type": "star"}]})).is_some());
        assert!(retro_unsupported(&json!({"conditions": [{"field": "from", "comparator": "contains", "value": "x"}], "actions": [{"type": "forward", "value": "a@b.c"}]})).is_some());
        assert!(retro_unsupported(&json!({"activeFrom": "2026-01-01T00:00:00Z", "conditions": [{"field": "from", "comparator": "contains", "value": "x"}], "actions": [{"type": "star"}]})).is_some());
        assert!(retro_unsupported(&json!({"conditions": [{"field": "from", "comparator": "contains", "value": "x"}], "actions": [{"type": "move", "value": "X"}]})).is_some());
    }

    #[test]
    fn stale_scan_is_dropped() {
        assert!(current(2, 2, true));
        assert!(!current(3, 2, true)); // rule B started after rule A
        assert!(!current(2, 2, false)); // dialog closed
    }

    #[test]
    fn apply_patches_and_if_in_state() {
        assert_eq!(step_patch("copy", "a/b~c"), json!({"mailboxIds/a~1b~0c": true}));
        assert_eq!(step_patch("keyword", "$label:x/y"), json!({"keywords/$label:x~1y": true}));
        assert_eq!(step_patch("move", "m1"), json!({"mailboxIds": {"m1": true}}));
        let steps = vec![("keyword".to_string(), vec!["e1".into(), "e2".into(), "e3".into()], "$seen".to_string()),
            ("copy".to_string(), vec!["e1".into()], "m2".to_string())];
        let mut sent = vec![];
        let r = apply_with(|c| { sent.push(c.clone()); let n = sent.len();
            let ids: Vec<String> = c[1]["update"].as_object().unwrap().keys().cloned().collect();
            Ok(json!(["Email/set", {"updated": ids.iter().map(|i| (i.clone(), Value::Null)).collect::<Map<_,_>>(), "newState": format!("s{n}")}, "a"])) }, "A", "s0".into(), &steps, 2);
        assert_eq!(r, Applied::Done(3));
        assert_eq!(sent.len(), 3);
        assert_eq!(sent[0][1]["ifInState"], "s0");
        assert_eq!(sent[1][1]["ifInState"], "s1");
        assert_eq!(sent[2][1]["ifInState"], "s2");
        assert_eq!(sent[2][1]["update"]["e1"], json!({"mailboxIds/m2": true}));
        // the state moved on: stop and say how much was done
        let mut n = 0;
        let r = apply_with(|_| { n += 1; Ok(if n == 1 { json!(["Email/set", {"updated": {"e1": null, "e2": null}, "newState": "s1"}, "a"]) } else { json!(["error", {"type": "stateMismatch"}, "a"]) }) }, "A", "s0".into(), &steps, 2);
        assert_eq!(r, Applied::Stale(2));
        assert!(applied_text(&r, 3).contains("2 of 3"));
        let r = apply_with(|_| Err("network down".into()), "A", "s0".into(), &steps, 2);
        assert_eq!(applied_text(&r, 3), "Applied to 0 of 3 messages: network down");
    }

    #[test]
    fn invalid_regex_is_refused() {
        let acts = vec![Act { kind: "mark_read".into(), ..Default::default() }];
        let bad = vec![Cond { field: "subject".into(), cmp: "regex".into(), value: "([a-z".into(), ..Default::default() }];
        assert!(build_rule(&Value::Null, None, "R", false, &bad, &acts, &folders(), false, false, "", "").unwrap_err().contains("not a valid regular expression"));
    }

    #[test]
    fn odd_header_names_stay_quoted() {
        let acts = vec![Act { kind: "mark_read".into(), ..Default::default() }];
        // names the generator would silently skip are refused in the editor
        for bad in ["X-A\"b", "X\\c", "X.Y", "X Y", "X:Y"] {
            let conds = vec![Cond { field: "header".into(), cmp: "contains".into(), value: "v".into(), header: bad.into() }];
            assert!(build_rule(&Value::Null, None, "R", false, &conds, &acts, &folders(), false, false, "", "").is_err(), "{bad}");
        }
        let conds = vec![Cond { field: "header".into(), cmp: "contains".into(), value: "v\"x\\y".into(), header: "X-Spam_Flag".into() }];
        let r = build_rule(&Value::Null, None, "R", false, &conds, &acts, &folders(), false, false, "", "").unwrap();
        let script = crate::sieve::generate_meta(&json!({"version": 1, "rules": [r.clone()]}), "", &[]);
        assert!(script.contains(r#"if header :contains "X-Spam_Flag" "v\"x\\y" {"#), "{script}");
        let p = retro_properties(&r);
        assert!(p.contains(&"header:X-Spam_Flag:asText:all".to_string()) && p.contains(&"header:X-Spam_Flag:all".to_string()), "{p:?}");
        let m = retro_message(&json!({"id": "e", "header:X-Spam_Flag:asText:all": ["v\"x\\y"], "header:X-Spam_Flag:all": [" v\"x\\y"]}));
        assert_eq!(m["headers"]["x-spam_flag"], json!(["v\"x\\y"]));
    }

    fn kinds(v: &[usize]) -> Vec<&'static str> { v.iter().map(|&i| ACTS[i].0).collect() }

    #[test]
    fn reject_is_offered_only_when_the_server_lists_it() {
        let none: Vec<String> = vec![];
        let listed = vec!["fileinto".to_string(), "reject".to_string()];
        assert!(!kinds(&offered_acts(&none, "move")).contains(&"reject"));
        assert!(kinds(&offered_acts(&listed, "move")).contains(&"reject"));
        // the other types do not depend on the server
        assert_eq!(kinds(&offered_acts(&none, "move")).len() + 1, kinds(&offered_acts(&listed, "move")).len());
        // an existing reject row keeps its own type, on a server without the extension too
        let row = kinds(&offered_acts(&none, "reject"));
        assert!(row.contains(&"reject"));
        assert_eq!(row.len(), kinds(&offered_acts(&none, "move")).len() + 1);
    }

    #[test]
    fn row_positions_map_back_to_the_same_type() {
        let none: Vec<String> = vec![];
        for current in ["move", "reject", "keep", "stop"] {
            let offer = offered_acts(&none, current);
            // the position a row shows for its type is the one the dropdown reports back
            let pos = offer.iter().position(|&j| ACTS[j].0 == current).unwrap();
            assert_eq!(ACTS[offer[pos]].0, current);
            assert!(offer.iter().all(|&j| ACTS[j].0 != "reject" || current == "reject"));
        }
    }

    #[test]
    fn existing_reject_rule_still_shows_and_is_not_dropped() {
        let none: Vec<String> = vec![];
        let conds = vec![Cond { field: "from".into(), cmp: "contains".into(), value: "spam@example.test".into(), ..Default::default() }];
        let acts = vec![Act { kind: "reject".into(), value: "Not accepted".into(), ..Default::default() }];
        let rule = build_rule(&Value::Null, Some("r1"), "Refuse", false, &conds, &acts, &folders(), false, false, "", "").unwrap();
        // the editor reads the rule back as a reject row and warns about the missing extension
        assert_eq!(crate::sieve::unsupported_actions(&rule, &none), vec!["reject".to_string()]);
        assert_eq!(acts_of(&rule)[0].kind, "reject");
        assert!(kinds(&offered_acts(&none, "reject")).contains(&"reject"));
        // saving keeps the action in the script and the metadata: nothing is dropped silently
        let script = crate::sieve::generate_meta(&json!({"version": 1, "rules": [rule.clone()]}), "", &none);
        assert!(script.contains("reject \"Not accepted\";"), "{script}");
        let back = crate::sieve::parse(&script);
        assert_eq!(back.metadata["rules"][0]["actions"][0]["type"], "reject");
        assert!(!back.locked);
        // a server that lists reject sees no warning
        let listed = vec!["reject".to_string()];
        assert!(crate::sieve::unsupported_actions(&rule, &listed).is_empty());
    }
}
